import sys
from collections import defaultdict

def is_rotationally_symmetric(n, m, segments):
    graph = defaultdict(set)
    for a, b in segments:
        graph[a].add(b)
        graph[b].add(a)

    visited = set()
    start = min(graph.keys())

    def dfs(node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor)

    dfs(start)

    return len(visited) == n

def main():
    n, m = map(int, input().split())
    segments = [tuple(map(int, input().split())) for _ in range(m)]

    result = is_rotationally_symmetric(n, m, segments)
    print("Yes" if result else "No")

if __name__ == "__main__":
    main()

def is_rotationally_symmetrical(n, m, segments):
    from collections import defaultdict
    from math import gcd

    def compute_gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    # Map each segment to its order of points (smaller index first)
    segment_orders = defaultdict(list)
    for a, b in segments:
        if a > b:
            a, b = b, a
        segment_orders[(a, b)].append((b - a) % n)

    # We need to check if there is a k such that all segment orders are multiples of k
    # i.e., for each unique segment, all order differences are consistent mod n
    for orders in segment_orders.values():
        if len(orders) > 1:
            common_gcd = orders[0]
            for order in orders[1:]:
                common_gcd = compute_gcd(common_gcd, order)
            if common_gcd == 1:
                return "No"

    return "Yes"

